package com.example.finance.student;
import com.example.finance.common.*;
import com.example.finance.ledger.*;
import com.example.finance.payment.*;
import com.example.finance.security.*;
import com.example.finance.tuition.*;
import jakarta.persistence.EntityManager;
import java.math.*;
import java.time.*;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class StudentFinanceService {
 private final EntityManager em; private final RemoteApi remote;
 @Value("${services.academic.url}") private String academic;
 public record Registration(Long enrollmentId,Long billingRootId,Long classId,String className,Long courseId,String courseName,Long branchId) {}
 public record Scopes(Long studentId,List<Registration> registrations) {}
 public record TuitionView(Long id,Long billingRootId,List<Long> enrollmentIds,String enrollmentLabel,String courseName,Long branchId,String currency,String originalAmount,String discountAmount,String totalAmount,String netPaid,String outstanding,String credit,LocalDate dueDate,String status,boolean overdue,boolean cancelled,String verification,String reviewCode,long version) {}
 public record Adjustment(Long id,String oldAmount,String newAmount,String oldDiscount,String newDiscount,LocalDate oldDueDate,LocalDate newDueDate,LocalDateTime date) {}
 public record TuitionDetail(TuitionView tuition,List<Adjustment> adjustments) {}
 public record Correction(Long id,String type,String amount,LocalDateTime date) {}
 public record ReceiptView(Long id,Long tuitionId,String receiptNo,LocalDateTime paidAt,String amount,String netAmount,String voidedAmount,String refundedAmount,String currency,String method,String state,String className,String courseName) {}
 public record ReceiptDetail(ReceiptView receipt,TuitionView tuition,List<Correction> corrections) {}
 public record Summary(String currency,int totalCount,int activeCount,int cancelledCount,int overdueCount,int reviewCount,int pendingBillingRoots,boolean coverageComplete,String totalAmount,String netPaid,String outstanding,String credit,OffsetDateTime asOf) {}
 private record Context(Scopes scopes,List<Tuition> rows,Map<Long,List<Payment>> payments,Map<Long,List<PaymentCorrection>> corrections) {}
 public static String money(BigDecimal value){return value==null?null:value.setScale(2,RoundingMode.UNNECESSARY).toPlainString();}
 private Scopes owner(){if(Users.current().role()!=Role.STUDENT)throw ApiException.forbidden();var s=remote.get(academic+"/api/v1/academic/student/me/billing-scopes",Scopes.class);if(s==null||s.studentId()==null||!Objects.equals(s.studentId(),Users.current().profileId())||s.registrations()==null)throw ApiException.forbidden();return s;}
 private Context context(){var scope=owner();var rows=em.createQuery("select t from Tuition t where t.studentId=:student order by t.dueDate,t.id",Tuition.class).setParameter("student",scope.studentId()).getResultList();Map<Long,List<Payment>> ps=new HashMap<>();Map<Long,List<PaymentCorrection>> cs=new HashMap<>();if(!rows.isEmpty()){var ids=rows.stream().map(Tuition::getId).toList();for(var p:em.createQuery("select p from Payment p where p.tuitionId in :ids order by p.paidAt desc,p.id desc",Payment.class).setParameter("ids",ids).getResultList())ps.computeIfAbsent(p.getTuitionId(),key->new ArrayList<>()).add(p);for(var c:em.createQuery("select c from PaymentCorrection c where c.tuitionId in :ids or c.paymentId in :payments order by c.createdAt,c.id",PaymentCorrection.class).setParameter("ids",ids).setParameter("payments",ps.values().stream().flatMap(Collection::stream).map(Payment::getId).toList()).getResultList())cs.computeIfAbsent(c.getTuitionId(),key->new ArrayList<>()).add(c);}return new Context(scope,rows,ps,cs);}
 private Registration registration(Context ctx,Tuition t){return ctx.scopes.registrations.stream().filter(r->Objects.equals(r.enrollmentId(),t.getEnrollmentId())&&Objects.equals(r.billingRootId(),r.enrollmentId())&&Objects.equals(r.classId(),t.getClassId())&&Objects.equals(r.branchId(),t.getBranchId())).findFirst().orElse(null);}
 private List<PaymentCorrection> corrections(Context ctx,Payment p){return ctx.corrections.values().stream().flatMap(Collection::stream).filter(c->c.getPaymentId().equals(p.getId())).toList();}
 private BigDecimal sum(List<PaymentCorrection> corrections,PaymentCorrection.Type type){return corrections.stream().filter(c->c.getType()==type).map(PaymentCorrection::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}
 private String receiptState(Context ctx,Payment p){var cs=corrections(ctx,p);var t=ctx.rows.stream().filter(v->v.getId().equals(p.getTuitionId())).findFirst().orElse(null);if(t==null||p.getStatus()!=Payment.Status.PAID||p.getAmount().signum()<=0||!Objects.equals(p.getBranchId(),t.getBranchId())||cs.stream().anyMatch(c->c.getAmount().signum()<=0||!Objects.equals(c.getTuitionId(),p.getTuitionId())||!Objects.equals(c.getBranchId(),p.getBranchId())))return "REVIEW_REQUIRED";var v=sum(cs,PaymentCorrection.Type.VOID);var r=sum(cs,PaymentCorrection.Type.REFUND);if(v.add(r).compareTo(p.getAmount())>0||v.signum()>0&&(r.signum()>0||v.compareTo(p.getAmount())!=0||cs.size()!=1))return "REVIEW_REQUIRED";return v.signum()>0?"VOIDED":r.compareTo(p.getAmount())==0?"REFUNDED":r.signum()>0?"PARTIALLY_REFUNDED":"VALID";}
 private BigDecimal net(Context ctx,Tuition t){return ctx.payments.getOrDefault(t.getId(),List.of()).stream().map(p->p.getAmount().subtract(sum(corrections(ctx,p),PaymentCorrection.Type.VOID)).subtract(sum(corrections(ctx,p),PaymentCorrection.Type.REFUND))).reduce(BigDecimal.ZERO,BigDecimal::add);}
 private String review(Context ctx,Tuition t){if(registration(ctx,t)==null)return t.getEnrollmentId()==null?"UNLINKED_LEGACY":"BILLING_LINK_UNVERIFIED";if(!"VND".equals(t.getCurrency()))return "UNSUPPORTED_CURRENCY";if(t.getAmount().signum()<0||t.getDiscountAmount()!=null&&t.getDiscountAmount().signum()<0||t.getOriginalAmount()!=null&&(t.getOriginalAmount().signum()<0||t.getOriginalAmount().subtract(t.getDiscountAmount()==null?BigDecimal.ZERO:t.getDiscountAmount()).compareTo(t.getAmount())!=0))return "INVALID_AMOUNT";var ps=ctx.payments.getOrDefault(t.getId(),List.of());if(ps.stream().anyMatch(p->receiptState(ctx,p).equals("REVIEW_REQUIRED")))return "RECEIPT_UNVERIFIED";if(ctx.corrections.getOrDefault(t.getId(),List.of()).stream().anyMatch(c->ps.stream().noneMatch(p->p.getId().equals(c.getPaymentId()))))return "CORRECTION_UNVERIFIED";if(net(ctx,t).signum()<0||net(ctx,t).compareTo(t.paid())!=0)return "LEDGER_MISMATCH";return null;}
 private TuitionView view(Context ctx,Tuition t){var r=registration(ctx,t);String review=review(ctx,t);boolean verified=review==null,cancelled=t.getStatus()==Tuition.Status.CANCELLED;var paid=verified?net(ctx,t):null;var remaining=verified?(cancelled?BigDecimal.ZERO:t.getAmount().subtract(paid).max(BigDecimal.ZERO)):null;var credit=verified?(cancelled?BigDecimal.ZERO:paid.subtract(t.getAmount()).max(BigDecimal.ZERO)):null;boolean overdue=verified&&!cancelled&&remaining.signum()>0&&t.getDueDate().isBefore(LocalDate.now(BusinessTime.ZONE));String status=!verified?"REVIEW_REQUIRED":cancelled?"CANCELLED":overdue?"OVERDUE":remaining.signum()==0?"PAID":paid.signum()>0?"PARTIAL":"UNPAID";var siblings=r==null?List.<Long>of():ctx.scopes.registrations.stream().filter(e->e.billingRootId().equals(r.enrollmentId())).map(Registration::enrollmentId).sorted().toList();return new TuitionView(t.getId(),r==null?null:r.enrollmentId(),siblings,r==null?"Khoản học phí cần xác minh":r.className(),r==null?null:r.courseName(),r==null?null:r.branchId(),t.getCurrency(),money(t.getOriginalAmount()==null?t.getAmount():t.getOriginalAmount()),money(t.getDiscountAmount()==null?BigDecimal.ZERO:t.getDiscountAmount()),money(t.getAmount()),money(paid),money(remaining),money(credit),t.getDueDate(),status,overdue,cancelled,verified?"VERIFIED":"REVIEW_REQUIRED",review,t.getVersion());}
 private Tuition require(Context ctx,Long id){return ctx.rows.stream().filter(t->t.getId().equals(id)).findFirst().orElseThrow(ApiException::missing);}
 private void page(int page,int size){if(page<0||size<1||size>100||(long)page*size>Integer.MAX_VALUE)throw ApiException.bad("Invalid page");}
 private <T> PageResponse<T> paginate(List<T> all,int page,int size){int from=Math.min(all.size(),page*size),to=Math.min(all.size(),from+size);return new PageResponse<>(all.subList(from,to),page,size,all.size(),(int)Math.ceil((double)all.size()/size));}
 public Map<Long,TuitionView> labels(Collection<Long> ids){
   if(ids.isEmpty())return Map.of();var ctx=context();var result=new HashMap<Long,TuitionView>();
   for(var t:ctx.rows)if(ids.contains(t.getId()))result.put(t.getId(),view(ctx,t));return result;
 }
 public PageResponse<TuitionView> list(int page,int size,String status,Boolean overdue,Long enrollment){page(page,size);if(status!=null&&!Set.of("UNPAID","PARTIAL","PAID","OVERDUE","CANCELLED","REVIEW_REQUIRED","DUE").contains(status))throw ApiException.bad("Invalid status");var ctx=context();Long root=enrollment==null?null:ctx.scopes.registrations.stream().filter(e->e.enrollmentId().equals(enrollment)).findFirst().orElseThrow(ApiException::missing).billingRootId();var rows=ctx.rows.stream().filter(t->root==null||Objects.equals(t.getEnrollmentId(),root)).map(t->view(ctx,t)).filter(v->status==null||v.status().equals(status)||"DUE".equals(status)&&!v.cancelled()&&(!"VERIFIED".equals(v.verification())||new BigDecimal(v.outstanding()).signum()>0)).filter(v->overdue==null||v.overdue()==overdue).toList();return paginate(rows,page,size);}
 public TuitionDetail detail(Long id){var ctx=context();var t=require(ctx,id);var a=em.createQuery("select a from TuitionAdjustment a where a.tuitionId=:id order by a.createdAt,a.id",TuitionAdjustment.class).setParameter("id",id).getResultList().stream().map(v->new Adjustment(v.getId(),money(v.getOldAmount()),money(v.getNewAmount()),money(v.getOldDiscount()),money(v.getNewDiscount()),v.getOldDueDate(),v.getNewDueDate(),v.getCreatedAt())).toList();return new TuitionDetail(view(ctx,t),a);}
 public Summary summary(){var ctx=context();var rows=ctx.rows.stream().map(t->view(ctx,t)).toList();var roots=new HashSet<>(ctx.scopes.registrations.stream().map(Registration::billingRootId).toList());ctx.rows.stream().filter(t->registration(ctx,t)!=null).forEach(t->roots.remove(t.getEnrollmentId()));int review=(int)rows.stream().filter(v->!v.verification().equals("VERIFIED")).count();boolean complete=review==0&&roots.isEmpty();var active=rows.stream().filter(v->!v.cancelled()&&v.verification().equals("VERIFIED")).toList();return new Summary("VND",rows.size(),active.size(),(int)rows.stream().filter(TuitionView::cancelled).count(),(int)active.stream().filter(TuitionView::overdue).count(),review,roots.size(),complete,complete?total(active,TuitionView::totalAmount):null,complete?total(active,TuitionView::netPaid):null,complete?total(active,TuitionView::outstanding):null,complete?total(active,TuitionView::credit):null,OffsetDateTime.now(BusinessTime.ZONE));}
 private String total(List<TuitionView> rows,java.util.function.Function<TuitionView,String> value){return money(rows.stream().map(value).map(BigDecimal::new).reduce(BigDecimal.ZERO,BigDecimal::add));}
 private ReceiptView receipt(Context ctx,Payment p){String state=receiptState(ctx,p);boolean valid=!state.equals("REVIEW_REQUIRED");var t=require(ctx,p.getTuitionId());var cs=corrections(ctx,p);var voided=sum(cs,PaymentCorrection.Type.VOID);var refunded=sum(cs,PaymentCorrection.Type.REFUND);return new ReceiptView(p.getId(),p.getTuitionId(),p.getReceiptNo(),p.getPaidAt(),money(p.getAmount()),valid?money(p.getAmount().subtract(voided).subtract(refunded)):null,valid?money(voided):null,valid?money(refunded):null,t.getCurrency(),p.getPaymentMethod().name(),state,view(ctx,t).enrollmentLabel(),view(ctx,t).courseName());}
 public PageResponse<ReceiptView> receipts(Long tuition,int page,int size){page(page,size);var ctx=context();if(tuition!=null)require(ctx,tuition);var ps=ctx.payments.values().stream().flatMap(Collection::stream).filter(p->tuition==null||p.getTuitionId().equals(tuition)).sorted(Comparator.comparing(Payment::getPaidAt).thenComparing(Payment::getId).reversed()).map(p->receipt(ctx,p)).toList();return paginate(ps,page,size);}
 public ReceiptDetail receipt(Long id){var ctx=context();var p=ctx.payments.values().stream().flatMap(Collection::stream).filter(v->v.getId().equals(id)).findFirst().orElseThrow(ApiException::missing);return new ReceiptDetail(receipt(ctx,p),view(ctx,require(ctx,p.getTuitionId())),corrections(ctx,p).stream().filter(c->c.getTuitionId().equals(p.getTuitionId())&&c.getBranchId().equals(p.getBranchId())).map(c->new Correction(c.getId(),c.getType().name(),money(c.getAmount()),c.getCreatedAt())).toList());}
}
